// Build the daily 8am WhatsApp summary
const items = $input.all();

// Get data from each branch
const memoryRaw = items[0]?.json?.stdout || '';
const filesRaw = items[1]?.json?.stdout || '';
const alertRaw = items[2]?.json?.stdout || '';

// Parse SESSION_MEMORY for key business figures
let maySales = 'N/A';
let avgDaily = 'N/A';
let gpMargin = 'N/A';
let pendingCheques = 'N/A';
let pendingTasks = [];

const memLines = memoryRaw.split('\n');
for (const line of memLines) {
  const l = line.toLowerCase();
  if (l.includes('may 2026 sales') || l.includes('sales (to')) {
    const m = line.match(/rs\.?\s*([\d,\.]+)/i);
    if (m) maySales = 'Rs. ' + m[1];
  }
  if (l.includes('avg') && l.includes('day')) {
    const m = line.match(/rs\.?\s*([\d,\.]+)/i);
    if (m) avgDaily = 'Rs. ' + m[1];
  }
  if (l.includes('gp') && l.includes('%')) {
    const m = line.match(/(\d+\.?\d*)%/);
    if (m) gpMargin = m[1] + '%';
  }
  if (l.includes('pending cheque') || l.includes('rs.49')) {
    const m = line.match(/rs\.?\s*([\d,\.]+m?)/i);
    if (m) pendingCheques = 'Rs. ' + m[1];
  }
  if (line.trim().match(/^\d+\./) && l.includes('fix') || l.includes('call') || l.includes('verify')) {
    pendingTasks.push(line.trim().slice(0, 60));
  }
}

// Parse recent files list
const recentFiles = filesRaw.trim().split('\n')
  .filter(l => l.trim())
  .slice(0, 3)
  .map(l => {
    const parts = l.split('|');
    return `📄 ${parts[0] || l}`;
  })
  .join('\n');

// Count alerts from yesterday
const hasYesterdayAlert = alertRaw.trim().length > 20;

// Build the morning summary
const now = new Date();
const dateStr = now.toLocaleDateString('en-GB', {
  timeZone: 'Asia/Colombo',
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

// Determine GP status emoji
const gpNum = parseFloat(gpMargin);
const gpEmoji = gpNum < 18 ? '🔴' : gpNum < 22 ? '🟡' : '🟢';

// Pending tasks (top 3)
const tasksText = pendingTasks.length > 0
  ? pendingTasks.slice(0, 3).map(t => `  • ${t}`).join('\n')
  : '  • None pending';

const summary = `🌅 *BATHCO MORNING BRIEFING*
━━━━━━━━━━━━━━━━━━━━
📅 ${dateStr}
⏰ 8:00 AM Daily Report

📊 *BUSINESS SNAPSHOT:*
💰 May Sales: ${maySales}
📈 Avg/Day: ${avgDaily}
${gpEmoji} GP Margin: ${gpMargin} (target: 25%+)
🏦 Pending Cheques: ${pendingCheques}

📁 *RECENT FILES:*
${recentFiles || '  No new files'}

${hasYesterdayAlert ? '⚠️ *UNRESOLVED ALERTS FROM YESTERDAY*\n  Check Desktop for BATHCO_ALERT_*.txt' : '✅ No unresolved alerts'}

📋 *PENDING ACTIONS:*
${tasksText}

━━━━━━━━━━━━━━━━━━━━
_Good morning, Ajmal 🙏_
_1st Choice Bathco | AI System_`;

return [{
  json: {
    summary,
    date: dateStr,
    maySales,
    gpMargin,
    pendingCheques,
    generatedAt: new Date().toISOString()
  }
}];
